import 'package:hive_ce/hive.dart';

import '../utilities/default_nodes.dart';

part 'type_adaptors/node_model.g.dart';

// @HiveType(typeId: 12)
class NodeModel {
  // Field numbers 5, 6, 8, 9, 10, 13 and 15 belonged to settings for other
  // coins' nodes; the adapter skips them in older records.

  // @HiveField(0)
  final String id;
  // @HiveField(1)
  final String host;
  // @HiveField(2)
  final int port;
  // @HiveField(3)
  final String name;
  // @HiveField(4)
  final bool useSSL;
  // @HiveField(7)
  final String coinName;
  // @HiveField(11)
  final bool torEnabled;
  // @HiveField(12)
  final bool clearnetEnabled;
  // @HiveField(14)
  final bool isPrimary;

  NodeModel({
    required this.host,
    required this.port,
    required this.name,
    required this.id,
    required this.useSSL,
    required this.coinName,
    required this.torEnabled,
    required this.clearnetEnabled,
    required this.isPrimary,
  });

  NodeModel copyWith({
    String? host,
    int? port,
    String? name,
    bool? useSSL,
    String? coinName,
    bool? torEnabled,
    bool? clearnetEnabled,
    bool? isPrimary,
  }) {
    return NodeModel(
      host: host ?? this.host,
      port: port ?? this.port,
      name: name ?? this.name,
      id: id,
      useSSL: useSSL ?? this.useSSL,
      coinName: coinName ?? this.coinName,
      torEnabled: torEnabled ?? this.torEnabled,
      clearnetEnabled: clearnetEnabled ?? this.clearnetEnabled,
      isPrimary: isPrimary ?? this.isPrimary,
    );
  }

  Map<String, dynamic> toMap() {
    final Map<String, dynamic> map = {};
    map['host'] = host;
    map['port'] = port;
    map['name'] = name;
    map['id'] = id;
    map['useSSL'] = useSSL;
    map['coinName'] = coinName;
    map['torEnabled'] = torEnabled;
    map['clearEnabled'] = clearnetEnabled;
    map['isPrimary'] = isPrimary;
    return map;
  }

  bool get isDefault => id.startsWith(DefaultNodes.defaultNodeIdPrefix);

  @override
  String toString() {
    return toMap().toString();
  }
}
